code.css:
.thread{display:flex;flex-direction:column;gap:16px;padding:16px}
.comment{display:flex;gap:12px}
.comment__avatar{border-radius:9999px;width:32px;height:32px;flex:none}
.comment__main{flex:1;min-width:0}
.comment__head{display:flex;gap:8px;align-items:baseline;font-size:12px;color:#525252}
.comment__author{font-weight:600;color:#111}
.comment__body{margin:4px 0 8px;font-size:14px;line-height:1.5}
.comment__actions{display:flex;gap:8px}
.comment__actions button{min-height:44px;padding:0 12px;border:1px solid #737373;border-radius:8px;background:#fff;cursor:pointer;font-size:13px}
.comment__actions button:hover{background:#f5f5f5}
.thread__composer{display:flex;gap:8px;align-items:flex-end}
.thread__composer textarea{flex:1;padding:12px;border:1px solid #737373;border-radius:8px;font:inherit;resize:vertical}
.btn{min-height:44px;padding:0 16px;border-radius:999px;border:1px solid #111;background:#111;color:#fff;cursor:pointer}
.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.comment__actions button:focus-visible,.thread__composer textarea:focus-visible,.btn:focus-visible{outline:2px solid #1d4ed8;outline-offset:2px}
